请对以下 case 进行三维加权评分。

=== case_id ===
Case-11-fitness-010

=== 用户原始指令 (query.txt) ===
一行带数字的字，点开能跳app，能读天气，完成的要标记

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "一行带数字的字，点开能跳app，能读天气，完成的要标记",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询位置的区县或当前位置展示名",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "28°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          },
          "airQuality": {
            "type": "string",
            "description": "当前空气质量等级",
            "sampleValue": "良"
          }
        }
      }
    },
    "status": {
      "completed": {
        "type": "boolean",
        "description": "当前运动提醒是否已完成",
        "sampleValue": true
      },
      "label": {
        "type": "string",
        "description": "完成状态标记短文本",
        "sampleValue": "已完成"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/cloudy.png",
      "description": "云朵组合彩色天气图标，适合表示多云或普通天气状态。"
    }
  ]
}

